<template><aside class="groups"><button :data-view="'all'" @click="ui.view='all';groups.selected=null">全部笔记</button><button data-view="trash" @click="ui.view='trash'">回收站</button><ul><li v-for="g in groups.items" :key="g.group_id" @click="groups.selected=g.group_id;ui.view='all'">{{g.name}}</li></ul><input v-model="newName" placeholder="新建分组" @keyup.enter="add"></aside></template><script setup lang="ts">import {ref} from 'vue';import {useGroupsStore} from '../stores/groups';import {useUiStore} from '../stores/ui';const groups=useGroupsStore(),ui=useUiStore(),newName=ref('');async function add(){if(newName.value.trim()){await groups.create(newName.value.trim());newName.value=''}}</script>
